11	// String wire leaves retain their domain names when used as schema definitions.
12	macro_rules! string_json_schema {
13	    ($name:ident) => {
14	        impl ::schemars::JsonSchema for $name {
15	            fn schema_name() -> String {
16	                stringify!($name).to_string()
17	            }
18	
19	            fn schema_id() -> ::std::borrow::Cow<'static, str> {
20	                ::std::borrow::Cow::Borrowed(concat!(module_path!(), "::", stringify!($name)))
21	            }
22	
23	            fn json_schema(generator: &mut ::schemars::gen::SchemaGenerator) -> ::schemars::schema::Schema {
24	                <String as ::schemars::JsonSchema>::json_schema(generator)
25	            }
26	        }
27	    };
28	}
