52	/// Package identity across ecosystems.
53	#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
54	#[serde(try_from = "String")]
55	pub enum PackageId {
56	    Bare(String),
57	    Prefixed { ecosystem: Ecosystem, name: String },
58	}
59	
60	string_json_schema!(PackageId);
61	
62	impl PackageId {
63	    /// Parses package identity string.
64	    ///
65	    /// # Errors
66	    ///
67	    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
68	    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
69	        if s.is_empty() {
70	            return Err(PackageIdParseError::Empty);
71	        }
72	        if s.starts_with('/') {
73	            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
74	        }
75	        if s.starts_with('-') {
76	            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
77	        }
78	        if s.contains("..") {
79	            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
80	        }
81	
82	        if let Some((prefix, remainder)) = s.split_once(':') {
83	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
84	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
85	                return Ok(PackageId::Prefixed {
86	                    ecosystem,
87	                    name: remainder.to_string(),
88	                });
89	            }
90	        }
91	
92	        if let Some((prefix, remainder)) = s.split_once('/') {
93	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
94	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
95	                return Ok(PackageId::Prefixed {
96	                    ecosystem,
97	                    name: remainder.to_string(),
98	                });
99	            }
100	        }
101	
102	        Ok(PackageId::Bare(s.to_string()))
103	    }
104	
105	    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
106	    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
107	    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
108	        if remainder.is_empty() {
109	            return Err(PackageIdParseError::EmptyNameAfterPrefix {
110	                raw: raw.to_string(),
111	                prefix: prefix.to_string(),
112	            });
113	        }
114	        if remainder.starts_with('-') {
115	            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
116	        }
117	        if remainder.contains("..") {
118	            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
119	        }
120	        Ok(())
121	    }
122	
123	    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
124	    pub fn display_name(&self) -> String {
125	        match self {
126	            PackageId::Bare(name) => name.clone(),
127	            PackageId::Prefixed { ecosystem, name } => {
128	                format!("{}/{}", ecosystem.prefix(), name)
129	            }
130	        }
131	    }
132	
133	    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
134	    pub fn ecosystem(&self) -> Option<Ecosystem> {
135	        match self {
136	            PackageId::Bare(_) => None,
137	            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
138	        }
139	    }
140	
141	    /// Returns the package name without any ecosystem prefix.
142	    pub fn name(&self) -> &str {
143	        match self {
144	            PackageId::Bare(name) => name,
145	            PackageId::Prefixed { name, .. } => name,
146	        }
147	    }
148	
149	    /// Weak "could be the same package" check, not strict equality.
150	    ///
151	    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
152	    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
153	    /// equality always matches.
154	    ///
155	    /// **Caller contract**: in a polyglot workspace, a bare lookup can match
156	    /// packages in two or more ecosystems (e.g. `foo` in both Cargo and npm).
157	    /// Callers must collect *all* matches and error on 2+ — see
158	    /// `aggregate::resolve_target_package`'s `AmbiguousName` pattern — never
159	    /// take the first match silently. A plain existence check (`.any()`) is
160	    /// safe only because the aggregation layer already rejects ambiguous
161	    /// references upstream.
162	    pub fn matches(&self, other: &Self) -> bool {
163	        if self == other {
164	            return true;
165	        }
166	        if self.name() == other.name() {
167	            match (self.ecosystem(), other.ecosystem()) {
168	                (None, _) | (_, None) => true,
169	                (Some(e1), Some(e2)) => e1 == e2,
170	            }
171	        } else {
172	            false
173	        }
174	    }
175	
176	    /// The single implementation of the collect-and-error pattern
177	    /// [`matches`](Self::matches)'s own doc comment requires every caller
178	    /// to hand-roll: filters `items` down to those whose id (via `id_of`)
179	    /// matches `self`, then resolves the result to exactly one, none, or
180	    /// reports the ambiguity.
181	    ///
182	    /// - `Ok(None)`: no item matches.
183	    /// - `Ok(Some(item))`: exactly one item matches -- the unambiguous case.
184	    /// - `Err(candidates)`: two or more items match. The caller decides how
185	    ///   to report this (e.g. as a domain-specific "ambiguous name" error
186	    ///   naming `self` and `candidates`) -- this method stays generic over
187	    ///   any `T` (a `Package`, a bare `PackageId`, ...) rather than forcing
188	    ///   a particular error type on every layer that needs this check.
189	    pub fn resolve_unique<'a, T>(
190	        &self,
191	        items: impl Iterator<Item = &'a T>,
192	        id_of: impl Fn(&'a T) -> &'a PackageId,
193	    ) -> Result<Option<&'a T>, Vec<&'a T>> {
194	        let matching: Vec<&'a T> = items.filter(|item| id_of(item).matches(self)).collect();
195	        match matching.len() {
196	            0 => Ok(None),
197	            1 => Ok(Some(matching[0])),
198	            _ => Err(matching),
199	        }
200	    }
201	}
