251	pub enum PackageIdParseError {
252	    #[error("package identity is empty")]
253	    Empty,
254	    #[error("package identity `{raw}` has ecosystem prefix `{prefix}` but no name after it")]
255	    EmptyNameAfterPrefix { raw: String, prefix: String },
256	    #[error("`{raw}` starts with `/`")]
