264	/// Defines the `as_str`/`Display` pair shared by every single-field `String`
265	/// newtype in this crate, regardless of how the rest of the type (fields,
266	/// derives, serde impls) is shaped.
267	macro_rules! string_newtype_display {
268	    ($name:ident) => {
269	        impl $name {
270	            #[doc = concat!("Returns the ", stringify!($name), " as a string slice.")]
271	            pub fn as_str(&self) -> &str {
272	                &self.0
273	            }
274	        }
275	
276	        impl ::std::fmt::Display for $name {
277	            fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
278	                f.write_str(&self.0)
279	            }
280	        }
281	    };
282	}
