286	/// Defines a plain single-field `String` newtype: the common derive list,
287	/// `#[schemars(with = "String")]`, transparent (unvalidated) serde, `as_str`,
288	/// and `Display`. For newtypes that validate on construction/deserialize
289	/// (e.g. [`TagName`](crate::tag::TagName), [`CommitSha`]), use
290	/// [`string_newtype_display!`] instead and hand-write the rest.
291	macro_rules! string_newtype {
292	    ($(#[$doc:meta])* $name:ident) => {
293	        $(#[$doc])*
294	        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
295	        #[schemars(with = "String")]
296	        #[serde(transparent)]
297	        pub struct $name(pub String);
298	
299	        string_newtype_display!($name);
300	    };
301	}
