358	impl CommitSha {
359	    /// Parses a 40-character hexadecimal Git commit SHA, trimming surrounding whitespace.
360	    ///
361	    /// # Errors
362	    ///
363	    /// Returns `Err(ModelError::InvalidCommitSha)` if the trimmed input is not exactly 40 ASCII hex digits.
364	    pub fn parse(s: &str) -> Result<Self, ModelError> {
365	        let trimmed = s.trim();
366	        if trimmed.len() != 40 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
367	            return Err(ModelError::InvalidCommitSha {
368	                raw: s.to_string(),
369	                reason: "must be exactly 40 hexadecimal characters".to_string(),
370	            });
371	        }
372	        Ok(CommitSha(trimmed.to_lowercase()))
373	    }
374	
375	    /// Returns the full 40-character lowercase hex SHA.
376	    pub fn as_str(&self) -> &str {
377	        &self.0
378	    }
379	
380	    /// Returns the first 7 characters of the SHA, matching git's short-ref convention.
381	    pub fn short(&self) -> &str {
382	        &self.0[..7]
383	    }
384	}
