403	#[cfg(test)]
404	pub(crate) fn assert_string_wire_schema<T>(value: &T, name: &str, wire: &str)
405	where
406	    T: JsonSchema + Serialize + serde::de::DeserializeOwned,
407	{
408	    assert_eq!(
409	        serde_json::to_string(value).unwrap(),
410	        serde_json::to_string(wire).unwrap()
411	    );
412	
413	    let root = serde_json::to_value(schemars::schema_for!(T)).unwrap();
414	    assert_eq!(root["title"], name);
415	    assert_eq!(root["type"], "string");
416	    assert_eq!(root["$schema"], "http://json-schema.org/draft-07/schema#");
417	
418	    let mut generator = schemars::gen::SchemaGenerator::default();
419	    let reference = serde_json::to_value(generator.subschema_for::<T>()).unwrap();
420	    assert_eq!(reference["$ref"], format!("#/definitions/{name}"));
421	    assert_eq!(
422	        generator.definitions()[name],
423	        <String as JsonSchema>::json_schema(&mut schemars::gen::SchemaGenerator::default())
424	    );
425	
426	    for invalid in [
427	        serde_json::json!({ "raw": wire }),
428	        serde_json::json!([wire]),
429	        serde_json::json!(1),
430	        serde_json::json!(true),
431	        serde_json::Value::Null,
432	    ] {
433	        assert!(serde_json::from_value::<T>(invalid).is_err());
434	    }
435	}
