561	    #[test]
562	    fn package_id_rejects_path_traversal() {
563	        assert!(PackageId::parse("/etc/passwd").is_err(), "must reject leading slashes");
564	
565	        let dotdot_err = PackageId::parse("../../secret").unwrap_err();
566	        assert!(
567	            matches!(dotdot_err, PackageIdParseError::PathTraversal { .. }),
568	            "expected PathTraversal for a genuine `..` traversal, got: {dotdot_err:?}"
569	        );
570	        assert!(
