576	    /// A leading `-` is not path traversal at all (no `..` anywhere in the
577	    /// input) -- it's rejected because it could be misread as a CLI flag by
578	    /// a shelled-out command downstream. The old shared `PathTraversal`
579	    /// variant's message ("contains path traversal `..`") was factually
580	    /// false for this input; it must get its own variant with an accurate
581	    /// message, for the bare form and both prefixed forms.
582	    #[test]
583	    fn package_id_rejects_leading_hyphen_with_accurate_error() {
584	        for input in ["-x", "cargo:-x", "cargo/-x"] {
585	            let err = PackageId::parse(input).unwrap_err();
586	            assert!(
587	                matches!(err, PackageIdParseError::LeadingHyphen { .. }),
588	                "expected LeadingHyphen for `{input}`, got: {err:?}"
589	            );
590	            let msg = err.to_string();
591	            assert!(
592	                !msg.contains(".."),
593	                "LeadingHyphen's message must not falsely claim `..` path traversal, got: {msg}"
594	            );
595	            assert!(
596	                msg.contains('-'),
597	                "LeadingHyphen's message should reference the offending `-`, got: {msg}"
598	            );
599	        }
600	    }
